--
-- Triggers `type_of_equipment`
--
DELIMITER $$
CREATE TRIGGER `trg_type_of_equipment_before_insert` BEFORE INSERT ON `type_of_equipment` FOR EACH ROW BEGIN
        DECLARE next_num INT;
        
        IF NEW.code IS NULL OR NEW.code = '' THEN
            SELECT COALESCE(MAX(CAST(code AS UNSIGNED)), 0) + 1 INTO next_num 
            FROM type_of_equipment;
            SET NEW.code = LPAD(next_num, 2, '0');
        END IF;
    END
$$
DELIMITER ;

